// Searchable catalog of official brand logos (Iconify "logos" + Simple Icons, both CC0), generated by
// scripts/generate-icon-catalog.mjs. Only the title index loads up front; logo SVGs load per first letter.

export interface CatalogIcon {
  title: string;
  dataUrl: string;
}

type Index = [title: string, chunk: string][];

const chunkLoaders = import.meta.glob<Record<string, string>>(['./icon-catalog/*.json', '!./icon-catalog/index.json'], {
  import: 'default',
});
const chunkCache = new Map<string, Promise<Record<string, string>>>();
let indexPromise: Promise<Index> | null = null;

const loadIndex = () => (indexPromise ??= import('./icon-catalog/index.json').then((m) => m.default as Index));

function loadChunk(chunk: string) {
  if (!chunkCache.has(chunk)) chunkCache.set(chunk, chunkLoaders[`./icon-catalog/${chunk}.json`]());
  return chunkCache.get(chunk)!;
}

const normalize = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, '');
const svgToDataUrl = (svg: string) => 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);

/** Ranks exact matches first, then prefix matches, then word-prefix and substring matches. */
export async function searchIcons(query: string, limit = 30): Promise<CatalogIcon[]> {
  const q = normalize(query);
  if (!q) return [];
  const index = await loadIndex();
  const scored: { title: string; chunk: string; score: number }[] = [];
  for (const [title, chunk] of index) {
    const t = normalize(title);
    let score = -1;
    if (t === q) score = 0;
    else if (t.startsWith(q)) score = 1;
    else if (title.toLowerCase().split(/[\s.-]+/).some((w) => normalize(w).startsWith(q))) score = 2;
    else if (t.includes(q)) score = 3;
    if (score >= 0) scored.push({ title, chunk, score });
  }
  const top = scored.sort((a, b) => a.score - b.score || a.title.length - b.title.length).slice(0, limit);
  const chunks = Object.fromEntries(
    await Promise.all([...new Set(top.map((t) => t.chunk))].map(async (c) => [c, await loadChunk(c)] as const)),
  );
  return top.map(({ title, chunk }) => ({ title, dataUrl: svgToDataUrl(chunks[chunk][title]) }));
}

/** Exact-name match for a tool or company, used to auto-suggest a logo. */
export async function findIcon(name: string) {
  const [best] = await searchIcons(name, 1);
  return best && normalize(best.title) === normalize(name) ? best : undefined;
}
